namespace DoonPanelPreview {
 public sealed partial class Workbench : Window {
  readonly PriceStore store; readonly StackPanel content=new StackPanel();
  readonly Brush green=new SolidColorBrush(Color.FromRgb(36,92,64));
  List<PriceRow> orders=new List<PriceRow>(); string orderFile="";
  public Workbench(PriceStore database){store=database;Title="度昂 · 订单与价格工作台 v0.3";Width=1260;Height=820;MinWidth=960;MinHeight=650;WindowStartupLocation=WindowStartupLocation.CenterScreen;FontFamily=new FontFamily("Microsoft YaHei UI");FontSize=14;Background=new SolidColorBrush(Color.FromRgb(244,246,244));
   var root=new DockPanel();Content=root;var foot=new TextBlock{Text="本地资料库 · 数据保存在程序旁的 data 文件夹 · 原币种金额预览 · 金蝶导出与 BOM 尚未接入",Padding=new Thickness(20,12,20,12),Background=Brushes.White};DockPanel.SetDock(foot,Dock.Bottom);root.Children.Add(foot);
   var top=new TextBlock{Text="DOON    订单与工程工作台     /     度昂账套",FontSize=21,FontWeight=FontWeights.SemiBold,Foreground=green,Padding=new Thickness(26,20,26,20),Background=Brushes.White};DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);
   var side=new StackPanel{Width=185,Margin=new Thickness(12)};DockPanel.SetDock(side,Dock.Left);root.Children.Add(side);side.Children.Add(Label("日常作业",12));side.Children.Add(Btn("订单识别与匹配",Orders));side.Children.Add(Btn("客户价格库",Prices));side.Children.Add(Btn("客户资料",Customers));side.Children.Add(Btn("成品名称对应表",ProductNames));side.Children.Add(Btn("金蝶成品与物料库",Materials));side.Children.Add(Btn("成品编码规则",()=>CodingView()));side.Children.Add(Label("后续模块",12));foreach(string name in new[]{"BOM 编制","魔你汇率换算"}){string n=name;side.Children.Add(Btn(n,()=>Placeholder(n)));}side.Children.Add(Label("独立桌面窗口\n无需浏览器\n\n真实价格保存在本机\n不会上传到公共仓库",12));
   root.Children.Add(new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Padding=new Thickness(24)});Orders();
  }
  TextBlock Label(string s,double size=14){return new TextBlock{Text=s,FontSize=size,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,12)};}
  Button Btn(string s,Action a){var b=new Button{Content=s,Padding=new Thickness(13,9,13,9),Margin=new Thickness(0,5,8,5),Background=Brushes.White,Foreground=green,BorderBrush=Brushes.LightGray,Cursor=Cursors.Hand};b.Click+=(x,e)=>{try{a();}catch(Exception ex){MessageBox.Show(this,ex.Message,"操作未完成",MessageBoxButton.OK,MessageBoxImage.Warning);}};return b;}
  void Heading(string title,string subtitle){content.Children.Clear();content.Children.Add(Label(title,26));content.Children.Add(Label(subtitle));}
  static string Pick(string title){var d=new OpenFileDialog{Title=title,Filter="Excel 工作簿 (*.xlsx)|*.xlsx",Multiselect=false};return d.ShowDialog()==true?d.FileName:null;}
  void Placeholder(string name){Heading(name,"此模块保留面板入口，业务功能尚未接入。");content.Children.Add(Label("本版已实现客户价格导入、本地保存、来源追溯，以及订单的客户识别和价格匹配。\n金蝶模板导出、工程 BOM 与汇率核算后续逐项接入。"));}
  void Customers(){var rows=store.All();Heading("客户资料","从报价单的客户编号、PI 与客户 PO 提取；不从文件名猜客户。");foreach(var g in rows.GroupBy(x=>x.Customer)){string id=g.Key;content.Children.Add(Btn((id==""?"待识别客户":id)+"  ·  "+g.Count()+" 条价格来源",()=>Prices(id)));}if(rows.Count==0)content.Children.Add(Label("价格库尚无资料。请先导入客户报价文件。"));}
  void Prices(){Prices(null);}
  void Prices(string customer){var all=store.All();Heading("客户价格库",all.Count+" 条来源明细 · "+all.Select(x=>x.Customer).Where(x=>x!="").Distinct().Count()+" 个客户 · 同一文件重复导入不会新增记录");content.Children.Add(Btn("导入价格 Excel",()=>{string file=Pick("导入客户报价 / PI");if(file==null)return;var parsed=PriceParser.Parse(file);int count=store.Import(parsed);Prices();Detail("价格导入结果","新增 "+count+" 条；识别 "+parsed.Rows.Count+" 条。\n待核对 "+parsed.Rows.Count(x=>x.Status!="可匹配")+" 条。\n\n"+string.Join("\n",parsed.Skipped)+"\n\n原件已按文件指纹完整归档；历史来源不会覆盖。",null);}));content.Children.Add(Label("自动匹配生成核对预览。零价、条件附加费、未知币种和不同报价需核对。"));
   Table((customer==null?all:all.Where(x=>x.Customer==customer)).Select(PriceMap).ToList(),row=>PriceDetail(all.First(x=>x.Id==row["记录ID"])));
  }
  static Dictionary<string,string> PriceMap(PriceRow p){return new Dictionary<string,string>{{"客户",p.Customer},{"图纸",p.Drawing},{"客款号",p.Model},{"SKU",p.Sku},{"色号",p.Color},{"镜片描述",p.Lens??""},{"类型",p.Kind},{"币种",p.Currency},{"原单单价文本",p.RawPrice},{"基础单价",p.BasePrice},{"电镀加价",p.Plating},{"MOQ加价",p.Moq},{"合计单价",p.UnitPrice},{"单位",p.Unit},{"状态",p.Status},{"来源数量",p.Quantity},{"PI",p.Pi},{"客户PO",p.Po},{"工作表",p.Sheet},{"来源行",p.Row.ToString()},{"来源文件",p.File},{"备注",p.Notes},{"单元格依据",p.Evidence},{"原图纸",p.RawDrawing},{"原款号",p.RawModel},{"原公式",p.Formula},{"来源哈希",p.Hash},{"记录ID",p.Id}};}
  void PriceDetail(PriceRow p){Detail("报价来源 · "+p.Customer+" / "+p.Drawing+" / "+p.Color,string.Join("\n\n",PriceMap(p).Select(x=>x.Key+"："+x.Value)),()=>{var d=new SaveFileDialog{Title="保存原件副本（请使用新文件名）",FileName=Path.GetFileNameWithoutExtension(p.File)+"-原件副本.xlsx",Filter="Excel (*.xlsx)|*.xlsx"};if(d.ShowDialog()==true){store.CopyOriginal(p,d.FileName);MessageBox.Show(this,"原件副本已保存，哈希一致。请用 Excel 打开编辑或打印。","保存完成");}});}
  void Orders(){Heading("订单识别与价格匹配","上传 Excel 后，自动识别客户编号、图纸、客款号和色号，查询本地价格库并计算原币种金额。");content.Children.Add(Btn("选择客户订单 Excel",()=>{string file=Pick("选择客户订单（只读解析）");if(file==null)return;var parsed=PriceParser.Parse(file);if(parsed.Rows.Count==0)throw new InvalidDataException("未识别到订单明细。当前支持 Drawing / Model / Colourway 等列，或对应中文字段；此文件需要增加字段映射。");orders=parsed.Rows;orderFile=parsed.Name;Orders();if(parsed.Skipped.Count>0)Detail("未解析工作表",string.Join("\n",parsed.Skipped),null);}));
   if(orders.Count==0){content.Children.Add(Label("价格库已有 "+store.All().Count+" 条来源明细。\n\n匹配顺序：客户 → 图纸／客款号 → 色号 → 单位与正式／样办类型 → 同单来源优先。\n未知客户、不同价格或缺少依据时保持待核对；原单已有价格不会被覆盖。\n\n目前支持与已提供 PI 相同或兼容表头的 .xlsx；其他版式会提示补充映射。"));return;}
   var prices=store.All();var output=new List<Dictionary<string,string>>();var results=new Dictionary<string,MatchResult>();foreach(var o in orders){var m=PriceMatcher.Match(o,prices);results[o.Id]=m;output.Add(new Dictionary<string,string>{{"客户",o.Customer},{"图纸",o.Drawing},{"客款号",o.Model},{"色号",o.Color},{"镜片描述",o.Lens??""},{"数量",o.Quantity},{"单位",o.Unit},{"匹配单价",m.Price},{"币种",m.Currency},{"匹配金额",m.Amount},{"状态",m.Status},{"说明",m.Reason},{"原单单价",o.UnitPrice},{"PI",o.Pi},{"客户PO",o.Po},{"工作表",o.Sheet},{"来源行",o.Row.ToString()},{"记录ID",o.Id}});}
   content.Children.Add(Label(orderFile+" · "+orders.Count+" 行 · 自动匹配 "+results.Values.Count(x=>x.Status=="已匹配"||x.Status=="原价一致")+" 行；其余保持待核对。\n金额未应用汇率、税率、折扣或取整；本页不写入金蝶、不修改订单原件。"));
   Table(output,row=>{var o=orders.First(x=>x.Id==row["记录ID"]);var m=results[o.Id];Detail("订单匹配依据",string.Join("\n",row.Select(x=>x.Key+"："+x.Value))+"\n\n价格候选（保留全部来源）\n\n"+string.Join("\n\n",m.Candidates.Select(p=>p.File+" / "+p.Sheet+" 第 "+p.Row+" 行\n"+p.Customer+" / "+p.Drawing+" / "+p.Model+" / "+p.Color+"\n"+p.Currency+" "+p.UnitPrice+" / "+p.Unit+"；"+p.Status+"\n"+p.Evidence+"\n"+p.Notes)),null,()=>CodingView(o));});
  }
  void Detail(string title,string text,Action save,Action coding=null){var d=new Window{Title=title,Owner=this,Width=740,Height=620,WindowStartupLocation=WindowStartupLocation.CenterOwner,FontFamily=FontFamily,FontSize=14};var panel=new DockPanel{Margin=new Thickness(24)};var actions=new WrapPanel();DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);if(save!=null)actions.Children.Add(Btn("保存原件副本",save));if(coding!=null)actions.Children.Add(Btn("填写成品编码",()=>{d.Close();coding();}));var close=Btn("关闭详情",()=>d.Close());close.IsCancel=true;actions.Children.Add(close);panel.Children.Add(new TextBox{Text=text,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,BorderThickness=new Thickness(0)});d.Content=panel;d.ShowDialog();}
  public void CheckViews(){Orders();Prices();Customers();ProductNames();Materials();CodingView();CodingLibrary();Placeholder("BOM 编制");if(content.Children.Count<2)throw new Exception("Empty view");}
  [STAThread] public static int Main(string[] args){string directory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data"),report=null;for(int i=0;i<args.Length-1;i++){if(args[i]=="--data")directory=args[i+1];if(args[i]=="--report")report=args[i+1];}try{
   if(args.Contains("--self-test")){string result=SelfTests.Run();if(report!=null)File.WriteAllText(report,result);return 0;}
   int inspect=Array.IndexOf(args,"--inspect-prices");if(inspect>=0){var f=PriceParser.Parse(args[inspect+1]);if(report!=null)File.WriteAllText(report,PriceParser.Json.Serialize(new{rows=f.Rows,skipped=f.Skipped,hash=f.Hash}));return 0;}
   using(var db=new PriceStore(directory)){int gi=Array.IndexOf(args,"--generate-code");if(gi>=0){var input=PriceParser.Json.Deserialize<CodingInput>(File.ReadAllText(args[gi+1]));var result=CodingEngine.Generate(input,db.CodingRules(),db.Names(),db.LensRules());if(report!=null)File.WriteAllText(report,PriceParser.Json.Serialize(result));return result.Valid?0:2;}int li=Array.IndexOf(args,"--import-lens-rules");if(li>=0){int added=db.ImportLensRules(args[li+1]);if(report!=null)File.WriteAllText(report,"lens-rules-added: "+added);return 0;}int ci=Array.IndexOf(args,"--import-coding-rules");if(ci>=0){var file=CodingParser.Parse(args[ci+1]);int added=db.ImportCoding(file);if(report!=null)File.WriteAllText(report,PriceParser.Json.Serialize(new{added=added,current=db.CodingRules().Count,hash=file.Hash,integrity=db.Integrity()}));return 0;}int mi=Array.IndexOf(args,"--import-materials");if(mi>=0){var material=MaterialParser.Parse(args[mi+1]);int addedMaterials=db.ImportMaterials(material);if(report!=null)File.WriteAllText(report,PriceParser.Json.Serialize(new{added=addedMaterials,recognized=material.Rows.Count,stored=db.MaterialCount(),skipped=material.Skipped,hash=material.Hash,integrity=db.Integrity()}));return 0;}int ni=Array.IndexOf(args,"--import-names");if(ni>=0){int addedNames=db.ImportNames(args[ni+1]);if(report!=null)File.WriteAllText(report,"names-added: "+addedNames);return 0;}int index=Array.IndexOf(args,"--import-prices");if(index>=0){if(index+1>=args.Length)throw new ArgumentException("缺少来源文件。");var parsed=PriceParser.Parse(args[index+1]);int added=db.Import(parsed);var summary=new{added=added,recognized=parsed.Rows.Count,customers=parsed.Rows.Select(x=>x.Customer).Distinct().ToArray(),bySheet=parsed.Rows.GroupBy(x=>x.Sheet).Select(g=>new{sheet=g.Key,count=g.Count()}),byStatus=parsed.Rows.GroupBy(x=>x.Status).Select(g=>new{status=g.Key,count=g.Count()}),skipped=parsed.Skipped,hash=parsed.Hash,integrity=db.Integrity(),stored=db.All().Count};if(report!=null)File.WriteAllText(report,PriceParser.Json.Serialize(summary));return 0;}
    var app=new Application();var window=new Workbench(db);if(args.Contains("--check-views")){window.CheckViews();window.Close();if(report!=null)File.WriteAllText(report,"views-ok");return 0;}app.Run(window);return 0;}
  }catch(Exception ex){if(report!=null)File.WriteAllText(report,"FAILED: "+ex.ToString());if(args.Length==0)MessageBox.Show("无法完成："+ex.Message,"度昂工作台");return 1;}}
 }
}
